from rdkit import Chem

def test(smi, name, fix_si=True):
    m = Chem.MolFromSmiles(smi, sanitize=False)
    if m is None:
        print(name, "PARSE FAIL"); return
    if fix_si:
        for b in m.GetBonds():
            if b.GetBeginAtom().GetSymbol() in ("Si","Au") or b.GetEndAtom().GetSymbol() in ("Si","Au"):
                b.SetBondType(Chem.BondType.SINGLE); b.SetIsAromatic(False)
    try:
        Chem.Kekulize(m, clearAromaticFlags=False)
        print(name, "kek OK")
    except Exception as e:
        print(name, "kek FAIL", str(e)[:70])

# full ligand aromatic network with N-Me instead of N-Si, N+Me
test("Cn1c(-c2[n+](C)c(-c3c(C)c4ccccc4n3C)c(C)cc2)c(C)c2ccccc12", "network_Me")
# with Si on all three N
test("[Si]n1c(-c2[n+]([Si])c(-c3c(C)c4ccccc4n3[Si])c(C)cc2)c(C)c2ccccc12", "network_Si")
# same but Au ring closure style
test("[Si]1n2c(-c3[n+]4c(-c5c(C)c6ccccc6n5[Si]4)c(C)cc3)c(C)c2ccccc21", "network_Si_ringclosures")
