import numpy as np
def read_xyz(f):
    with open(f) as fh:
        lines = fh.readlines()
    n = int(lines[0])
    atoms, coords = [], []
    for i in range(2, 2+n):
        p = lines[i].split()
        atoms.append(p[0]); coords.append([float(x) for x in p[1:4]])
    return atoms, np.array(coords)

atoms, c = read_xyz("optimized.xyz")
def dist(i,j): return np.linalg.norm(c[i]-c[j])
def angle(i,j,k):
    v1 = c[i]-c[j]; v2 = c[k]-c[j]
    cos = np.dot(v1,v2)/np.linalg.norm(v1)/np.linalg.norm(v2)
    return np.degrees(np.arccos(np.clip(cos,-1,1)))
print("Si0-Au1 dist:", round(dist(0,1),3))
print("Au1-Si2 dist:", round(dist(1,2),3))
print("Si-Au-Si angle:", round(angle(0,1,2),2))
# Si-N bonds
for si, name in [(0,"Si0"),(2,"Si2")]:
    for ni in [a for a in range(len(atoms)) if atoms[a]=="N"]:
        d = dist(si,ni)
        if d < 2.3:
            print(name,"- N",ni, round(d,3))
